// Subset of upstream protobuf 2.6.0 generated_enum_reflection.h: the declarations generated
// .pb.h files with enums reference (NameOfEnum and ParseNamedEnum live in
// generated_message_reflection.cc). is_proto_enum is left out, and with it template_util.h.

#pragma once

#include "stubs/common.h"

namespace google {
namespace protobuf {
  class EnumDescriptor;
}  // namespace protobuf

namespace protobuf {

// Returns the EnumDescriptor for enum type E, which must be a
// proto-declared enum type.  Code generated by the protocol compiler
// will include specializations of this template for each enum type declared.
template <typename E>
const EnumDescriptor* GetEnumDescriptor();

namespace internal {

// Helper for parsing enums from strings.
bool ParseNamedEnum(const EnumDescriptor* descriptor,
                    const blz::string& name,
                    int* value);

template<typename EnumType>
bool ParseNamedEnum(const EnumDescriptor* descriptor,
                    const blz::string& name,
                    EnumType* value) {
  int tmp;
  if (!ParseNamedEnum(descriptor, name, &tmp)) return false;
  *value = static_cast<EnumType>(tmp);
  return true;
}

// Just a wrapper around printing the name of a value. The main point of this
// function is not to be inlined, so that you can do this without including
// descriptor.h.
const blz::string& NameOfEnum(const EnumDescriptor* descriptor, int value);

}  // namespace internal
}  // namespace protobuf
}  // namespace google
